'use client'

import Image from 'next/image'

interface Logo {
    name: string
    imageUrl?: string
    description?: string
}

interface BlockLogoShowcaseData {
    logos: Logo[]
}

interface BlockLogoShowcaseProps {
    data: BlockLogoShowcaseData
}

export default function BlockLogoShowcase({ data }: BlockLogoShowcaseProps) {
    const { logos } = data

    return (
        <div className="grid grid-cols-2 md:grid-cols-3 gap-8 items-center justify-items-center">
            {logos.map((logo, index) => (
                <div
                    key={index}
                    className="bg-white border border-gray-200 rounded-xl overflow-hidden"
                >
                    {/* Logo Preview */}
                    <div className="h-40 bg-gray-50 flex items-center justify-center p-8 relative">
                        {logo.imageUrl ? (
                            <Image
                                src={logo.imageUrl}
                                alt={logo.name}
                                fill
                                className="object-contain p-8"
                                sizes="(max-width: 768px) 50vw, 33vw"
                            />
                        ) : (
                            <div className="text-gray-400 text-center">
                                <div className="text-4xl font-bold mb-2">LOGO</div>
                                <div className="text-sm">{logo.name}</div>
                            </div>
                        )}
                    </div>

                    {/* Info */}
                    <div className="p-4 border-t border-gray-100">
                        <h4 className="font-semibold text-gray-900 text-sm">{logo.name}</h4>
                        {logo.description && (
                            <p className="text-gray-500 text-xs mt-1">{logo.description}</p>
                        )}
                    </div>
                </div>
            ))}
        </div>
    )
}
